import pytest
from graph import topo_sort

def ok(order, deps):
    pos = {n: i for i, n in enumerate(order)}
    return all(pos[d] < pos[n] for n, ds in deps.items() for d in ds)

def test_order():
    deps = {'a': ['b', 'c'], 'b': ['c'], 'd': []}
    out = topo_sort(deps)
    assert set(out) == {'a', 'b', 'c', 'd'} and ok(out, deps)

def test_cycle():
    with pytest.raises(ValueError):
        topo_sort({'a': ['b'], 'b': ['a']})

def test_self():
    with pytest.raises(ValueError):
        topo_sort({'a': ['a']})

import pytest
from roman import to_roman, from_roman

def test_round_trip():
    for n in range(1, 4000):
        assert from_roman(to_roman(n)) == n
    assert to_roman(1994) == 'MCMXCIV'

def test_bad():
    for bad in ['IIII', 'VX', 'IC', '', 'MMMM']:
        with pytest.raises(ValueError):
            from_roman(bad)

def test_range():
    for n in [0, 4000, -1]:
        with pytest.raises(ValueError):
            to_roman(n)
